package com.github.se.jdrnexus.ui.dice

/**
 * Represents the different types of dice available in the application. Each dice type defines its
 * maximum possible roll value.
 */
enum class DiceType(val maxValue: Int) {
  D4(4),
  D6(6),
  D8(8),
  D10(10),
  D12(12),
  D20(20),
}

/**
 * Represents the final result of a single dice roll. This is an immutable data class generated by
 * the DiceLogic.
 *
 * @property diceType The type of dice that was rolled.
 * @property rawValue The raw random value generated (between 1 and the dice's maxValue).
 * @property modifier The modifier applied to the raw value.
 * @property totalValue The final computed result (rawValue + modifier).
 */
data class DiceRollResult(
    val diceType: DiceType,
    val rawValue: Int,
    val modifier: Int,
    val totalValue: Int,
)

/**
 * Represents the current state of the Dice UI. The UI layer should observe this state to update its
 * visual components accordingly.
 *
 * @property selectedDice The currently selected dice type. Defaults to D20.
 * @property modifier The current modifier to be applied on the next roll.
 * @property currentResult The result of the last roll, or null if no roll has been made yet.
 * @property isRolling A boolean indicating if a roll animation/calculation is currently in
 *   progress. The UI should disable the "Roll" button when this is true.
 * @property errorMessage A user-friendly error message (e.g., if saving to the repository fails).
 *   Null if there are no errors.
 */
data class DiceUiState(
    val selectedDice: DiceType = DiceType.D20,
    val modifier: Int = 0,
    val currentResult: DiceRollResult? = null,
    val isRolling: Boolean = false,
    val errorMessage: String? = null,
)
